   [149]={next_id=150, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="太久没进来，我竟然忽略了这一点。", msg_color="", msg_size=0, talker="蒂雅", audio="", img="arts/ui/bg/story/storybg_14_113.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [150]={next_id=151, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="要是被族里那些长老们发现我们擅自闯入这里，免不了有许多麻烦。", msg_color="", msg_size=0, talker="蒂雅", audio="", img="arts/ui/bg/story/storybg_14_113.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [151]={next_id=152, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她拉着你快步走向观测台后方。那里有一个古老的木质柜子，柜门半掩，上面刻着星辰的花纹。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_113.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [152]={next_id=153, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们快进去！", msg_color="", msg_size=0, talker="蒂雅", audio="", img="arts/ui/bg/story/storybg_14_113.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [153]={next_id=154, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="小时候，我就是躲在这里避开守卫的巡逻的！", msg_color="", msg_size=0, talker="蒂雅", audio="", img="arts/ui/bg/story/storybg_14_113.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [154]={next_id=155, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你钻了进去。柜子里的空间很狭小，堆着一些旧布和几本发霉的书，空气中弥漫着陈旧的木头味道。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_113.jpg", video_url="", music_id="96", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [155]={next_id=156, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蒂雅跟着钻了进来，轻轻拉上柜门。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_113.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [156]={next_id=157, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="柜子里一片漆黑，只有门缝里透进来一丝微弱的光线。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_113.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [157]={next_id=158, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但你们忽略了一点，这个柜子原本是供小时候的蒂雅一人躲藏的，如今却挤进了你们二人，导致你们只能面对面紧紧贴在一起。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_113.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
