   [197]={next_id=198, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她转过身看着你，脸上的表情已经恢复了七八分从容，但脸颊上还泛着浅浅的红。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_113.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
